-- GENERATED by scripts/keybinds.py from ~/.config/hypr/keybinds.json.
-- Edit shortcuts in the "Keyboard Shortcuts" app; changes made here are overwritten.

-- Number-row keys by physical keycode (works on AZERTY too). Digit d -> 1..9 => 10..18, 0 => 19
local function digitCode(d)
    return "code:" .. (d == 0 and 19 or (9 + d))
end

local function zoomfunction(value)
    local z = hl.get_config("cursor:zoom_factor") + value
    hl.config({ cursor = { zoom_factor = math.max(1.0, math.min(3.0, z)) } })
end

-- Empty submap the Keyboard Shortcuts app switches to while recording a shortcut, so
-- existing binds don't fire. Emergency exit: Super+Ctrl+Alt+Escape.
hl.define_submap("keycapture", function()
    hl.bind("SUPER + CONTROL + ALT + Escape", hl.dsp.submap("reset"))
end)


-- Windows
hl.bind("SUPER + Escape", hl.dsp.exec_cmd("~/.config/hypr/scripts/shell-cmd.sh panel-toggle session"), { description = "Power menu" })
hl.bind("SUPER + Q", hl.dsp.exec_cmd("~/.config/hypr/scripts/pip-toggle.sh"), { description = "Picture-in-Picture (open / close)" })
hl.bind("SUPER + Z", hl.dsp.exec_cmd("qs -c isla ipc call isla phonemode"), { description = "Phone: overlay ↔ window" })
hl.bind("SUPER + D", hl.dsp.exec_cmd("~/.config/hypr/scripts/shell-cmd.sh bar-toggle"), { description = "Show / hide top bar" })
hl.bind("SUPER + W", hl.dsp.window.close(), { description = "Close window" })
hl.bind("SUPER + A", hl.dsp.window.float({ action = "toggle" }), { description = "Toggle floating" })
hl.bind("SUPER + ALT + Space", hl.dsp.window.fullscreen({ mode = 1 }), { description = "Maximize window" })
hl.bind("SUPER + F", hl.dsp.window.fullscreen(), { description = "Fullscreen" })
hl.bind("SUPER + J", hl.dsp.layout("togglesplit"), { description = "Toggle split direction" })
hl.bind("SUPER + E", hl.dsp.window.set_prop({ prop = "opaque", value = "toggle" }), { description = "Toggle full opacity" })

-- Focus & move
hl.bind("SUPER + Left", hl.dsp.exec_cmd("~/.config/hypr/scripts/smart-move.sh left"), { description = "Focus / move left (floating windows get tiled)" })
hl.bind("SUPER + Right", hl.dsp.exec_cmd("~/.config/hypr/scripts/smart-move.sh right"), { description = "Focus / move right (floating windows get tiled)" })
hl.bind("SUPER + Up", hl.dsp.focus({ direction = "up" }), { description = "Focus up" })
hl.bind("SUPER + Down", hl.dsp.focus({ direction = "down" }), { description = "Focus down" })
hl.bind("ALT + Tab", hl.dsp.window.cycle_next(), { description = "Next window" })
hl.bind("SUPER + Tab", hl.dsp.exec_cmd("~/.config/hypr/scripts/shell-cmd.sh islands"), { description = "Islands (workspaces)" })
hl.bind("CONTROL + Tab", hl.dsp.focus({ monitor = "+1" }), { description = "Jump to the other screen" })
hl.bind("SUPER + SHIFT + Up", hl.dsp.window.move({ direction = "u" }), { description = "Move window up" })
hl.bind("SUPER + SHIFT + Right", hl.dsp.window.move({ direction = "r" }), { description = "Move window right" })
hl.bind("SUPER + SHIFT + Left", hl.dsp.window.move({ direction = "l" }), { description = "Move window left" })
hl.bind("SUPER + SHIFT + Down", hl.dsp.window.move({ direction = "d" }), { description = "Move window down" })
hl.bind("SUPER + SHIFT + mouse_up", hl.dsp.window.move({ monitor = "-1" }), { description = "Move window to previous screen" })
hl.bind("SUPER + SHIFT + mouse_down", hl.dsp.window.move({ monitor = "+1" }), { description = "Move window to next screen" })

-- Workspaces
for i = 1, 9 do  -- Show workspace N on this screen
    hl.bind("SUPER + " .. digitCode(i), hl.dsp.exec_cmd("~/.config/hypr/scripts/ws.sh go " .. i), { description = "Show workspace N on this screen" })
end
for i = 1, 9 do  -- Move window to workspace N (follow)
    hl.bind("SUPER + SHIFT + " .. digitCode(i), hl.dsp.exec_cmd("~/.config/hypr/scripts/ws.sh move " .. i), { description = "Move window to workspace N (follow)" })
end
for i = 1, NUM_WPM do  -- Go to workspace N (absolute)
    hl.bind("SUPER + ALT + " .. digitCode(i % 10), hl.dsp.focus({ workspace = i }), { description = "Go to workspace N (absolute)" })
end
for i = 1, NUM_WPM do  -- Move window to workspace N on this screen
    hl.bind("SUPER + SHIFT + CONTROL + " .. digitCode(i % 10), hl.dsp.window.move({ workspace = "m~" .. i }), { description = "Move window to workspace N on this screen" })
end
for i = 1, NUM_WPM do  -- Move window to workspace N (stay)
    hl.bind("SUPER + SHIFT + ALT + " .. digitCode(i % 10), hl.dsp.window.move({ workspace = "m~" .. i, follow = false }), { description = "Move window to workspace N (stay)" })
end
hl.bind("SUPER + CONTROL + Right", hl.dsp.focus({ workspace = "m+1" }), { description = "Next workspace" })
hl.bind("SUPER + CONTROL + Left", hl.dsp.focus({ workspace = "m-1" }), { description = "Previous workspace" })
hl.bind("SUPER + CONTROL + Down", hl.dsp.focus({ workspace = "emptym" }), { description = "First empty workspace" })
hl.bind("SUPER + CONTROL + SHIFT + Right", hl.dsp.window.move({ workspace = "m+1" }), { description = "Move window to next workspace" })
hl.bind("SUPER + CONTROL + SHIFT + Left", hl.dsp.window.move({ workspace = "m-1" }), { description = "Move window to previous workspace" })
hl.bind("SUPER + mouse_down", hl.dsp.focus({ workspace = "m-1" }), { description = "Previous workspace (scroll)" })
hl.bind("SUPER + mouse_up", hl.dsp.focus({ workspace = "m+1" }), { description = "Next workspace (scroll)" })
hl.bind("SUPER + CONTROL + mouse_up", hl.dsp.focus({ workspace = "m-1" }), { description = "Previous workspace (Ctrl+scroll)" })
hl.bind("SUPER + CONTROL + mouse_down", hl.dsp.focus({ workspace = "m+1" }), { description = "Next workspace (Ctrl+scroll)" })
hl.bind("SUPER + CONTROL + SHIFT + mouse_up", hl.dsp.window.move({ workspace = "m-1" }), { description = "Move window to previous workspace (scroll)" })
hl.bind("SUPER + CONTROL + SHIFT + mouse_down", hl.dsp.window.move({ workspace = "m+1" }), { description = "Move window to next workspace (scroll)" })

